#include "human_store.hpp"
#include "json_store.hpp"
#include <cmath>
#include <limits>
#include <set>
namespace mousebox::application {
namespace {
void require(bool b,const char* text){if(!b)throw std::runtime_error(text);}
double number(const Json& o,const char* key){require(o.contains(key)&&o.at(key).is_number(),"模型数值缺失或不合法");const auto value=o.at(key).get<double>();require(std::isfinite(value),"模型数值不合法");return value;}
unsigned count(const Json& o,const char* key){const auto v=number(o,key);require(v>=0&&v<=std::numeric_limits<unsigned>::max()&&std::floor(v)==v,"模型计数不合法");return static_cast<unsigned>(v);}
ModelFileKind kind(const Json& o){if(o.value("format",std::string{})=="mousebox-human-ridge"&&o.value("version",0)==1)return ModelFileKind::LegacyPointing;if(o.value("format",std::string{})=="mousebox-speed-profile"&&o.value("version",0)==2)return ModelFileKind::Speed;return ModelFileKind::Unknown;}
Json canonicalLegacy(Json value){if(value.is_number_float()){const double n=value.get<double>();if(std::isfinite(n)&&std::floor(n)==n&&std::abs(n)<9007199254740992.0)return static_cast<std::int64_t>(n);}else if(value.is_array()||value.is_object())for(auto& v:value)v=canonicalLegacy(std::move(v));return value;}
}
bool saveMouseTrials(const std::filesystem::path& path,const std::vector<control::MouseTrial>& trials){Json list=Json::array();for(const auto& t:trials){Json samples=Json::array();for(const auto& p:t.samples)samples.push_back({p.us,p.x,p.y});list.push_back({{"dpi",t.dpi},{"session",t.session},{"samples",std::move(samples)}});}return storage::save(path,{{"format","mousebox-human-motion"},{"version",2},{"purpose","speed_only"},{"coordinates","raw_cumulative_counts"},{"time","consumer_observed_monotonic_us"},{"trials",std::move(list)}});}
std::vector<control::MouseTrial> loadMouseTrials(const std::filesystem::path& path){const auto o=storage::load(path,128*1024*1024);const auto version=o.value("version",0);require(o.value("format",std::string{})=="mousebox-human-motion"&&(version==1||version==2)&&o.value("coordinates",std::string{})=="raw_cumulative_counts"&&o.value("time",std::string{})=="consumer_observed_monotonic_us"&&o.contains("trials")&&o["trials"].is_array(),"采样格式或时间单位不支持");const auto& list=o["trials"];require(list.size()<=1000,"采样段数量超限");const auto legacy="legacy-"+storage::sha256(canonicalLegacy(o).dump());std::vector<control::MouseTrial> result;std::size_t total=0;for(const auto& record:list){require(record.is_object(),"采样段缺失");const auto dpi=count(record,"dpi");require(dpi>=100&&dpi<=32000,"采集DPI不合法");control::MouseTrial trial;trial.dpi=dpi;trial.session=version==1?legacy:record.value("session",std::string{});require(!trial.session.empty()&&trial.session.size()<=200&&record.contains("samples")&&record["samples"].is_array(),"采集场次或采样点缺失");const auto& samples=record["samples"];total+=samples.size();require(samples.size()<=200000&&total<=2000000,"采样数量超限");for(const auto& p:samples){require(p.is_array()&&p.size()==3&&p[0].is_number()&&p[1].is_number()&&p[2].is_number(),"采样点格式不合法");const auto us=p[0].get<double>(),x=p[1].get<double>(),y=p[2].get<double>();require(std::isfinite(us)&&us>=0&&us<=15000000&&std::floor(us)==us&&std::isfinite(x)&&std::isfinite(y)&&std::abs(x)<=10000000&&std::abs(y)<=10000000,"采样点范围不合法");const auto time=static_cast<std::uint64_t>(us);require(trial.samples.empty()||time>=trial.samples.back().us,"采样时间倒退");trial.samples.push_back({time,x,y});}result.push_back(std::move(trial));}return result;}
std::vector<control::MouseTrial> loadMouseTrialFiles(const std::vector<std::filesystem::path>& paths){require(!paths.empty(),"请选择采样文件");std::vector<control::MouseTrial> result;std::set<std::string> loaded;std::size_t total=0;for(const auto& path:paths){auto trials=loadMouseTrials(path);std::set<std::string> sessions;require(result.size()+trials.size()<=1000,"合并采样段数量超限");for(const auto& t:trials){require(!loaded.contains(t.session),"所选文件包含同一场次的重复快照；请只保留该场次最新的一份");sessions.insert(t.session);total+=t.samples.size();require(total<=2000000,"合并采样数量超限");}loaded.insert(sessions.begin(),sessions.end());for(auto& t:trials)result.push_back(std::move(t));}return result;}
bool saveHumanModel(const std::filesystem::path& path,const control::HumanMotionModel& m){if(!m.valid())return false;return storage::save(path,{{"format","mousebox-speed-profile"},{"version",2},{"reference_dpi",1600},{"sessions",m.sessions},{"training_sessions",m.trainingSessions},{"validation_sessions",m.validationSessions},{"trials",m.trials},{"training_rows",m.trainingRows},{"validation_rows",m.validationRows},{"moving_seconds",m.movingSeconds},{"speed50",m.speed50},{"speed90",m.speed90},{"speed95",m.speed95},{"acceleration90",m.acceleration90},{"braking90",m.braking90},{"log_speed_mean",m.logSpeedMean},{"log_speed_sigma",m.logSpeedSigma},{"validation_speed90",m.validationSpeed90},{"validation_relative_gap",m.validationRelativeGap}});}
control::HumanMotionModel loadHumanModel(const std::filesystem::path& path){const auto o=storage::load(path,1024*1024);require(kind(o)==ModelFileKind::Speed&&o.value("reference_dpi",0)==1600,"需要新版速度模型；旧版点选模型只能删除，不能用于控制");control::HumanMotionModel m;m.sessions=count(o,"sessions");m.trainingSessions=count(o,"training_sessions");m.validationSessions=count(o,"validation_sessions");m.trials=count(o,"trials");m.trainingRows=count(o,"training_rows");m.validationRows=count(o,"validation_rows");m.movingSeconds=number(o,"moving_seconds");m.speed50=number(o,"speed50");m.speed90=number(o,"speed90");m.speed95=number(o,"speed95");m.acceleration90=number(o,"acceleration90");m.braking90=number(o,"braking90");m.logSpeedMean=number(o,"log_speed_mean");m.logSpeedSigma=number(o,"log_speed_sigma");m.validationSpeed90=number(o,"validation_speed90");m.validationRelativeGap=number(o,"validation_relative_gap");require(m.valid(),"模型覆盖范围或速度参数不合法");return m;}
ModelFileKind humanModelFileKind(const std::filesystem::path& path){return kind(storage::load(path,1024*1024));}
bool removeHumanModel(const std::filesystem::path& path){require(humanModelFileKind(path)!=ModelFileKind::Unknown,"该文件不是本项目模型；采样和其他文件不会删除");std::error_code ec;const auto canonical=std::filesystem::canonical(path,ec);if(ec)return false;return std::filesystem::remove(canonical,ec)&&!ec;}
}
